import PropTypes from 'prop-types';
import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { makeStyles } from '@material-ui/core/styles';
import { Box, Card, CardContent, Typography, Grid, Dialog } from '@material-ui/core';

const useStyles = makeStyles((theme) => ({
  root: {
    height: '100%',
    transition: 'all 0.25s',
    cursor: 'pointer',
    '&:hover': {
      transform: 'translateY(-5px)',
    },
  },
  img: {
    width: '5rem',
    height: '5rem',
    objectFit: 'contain',
  },
  dialog: {
    padding: theme.spacing(3),
  },
  subFeatureCard: {
    marginBottom: theme.spacing(2),
    transition: 'all 0.25s',
    '&:hover': {
      transform: 'translateY(-3px)',
    },
  }
}));

function FeatureBox({ imgUrl, title, subTitle, to, subFeatures }) {
  const classes = useStyles();
  const [open, setOpen] = useState(false);

  const handleClick = () => {
    if (subFeatures) {
      setOpen(true);
    }
  };

  return (
    <>
      <Card className={classes.root} onClick={handleClick}>
        {!subFeatures ? (
          <Link to={to} style={{ textDecoration: 'none', color: 'inherit' }}>
            <CardContent>
              <Box display="flex" alignItems="center">
                <img className={classes.img} src={imgUrl} alt={title} />
                <Box ml={3}>
                  <Typography variant="h6">{title}</Typography>
                  <Typography variant="body2" color="textSecondary">
                    {subTitle}
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Link>
        ) : (
          <CardContent>
            <Box display="flex" alignItems="center">
              <img className={classes.img} src={imgUrl} alt={title} />
              <Box ml={3}>
                <Typography variant="h6">{title}</Typography>
                <Typography variant="body2" color="textSecondary">
                  {subTitle}
                </Typography>
              </Box>
            </Box>
          </CardContent>
        )}
      </Card>

      <Dialog 
        open={open} 
        onClose={() => setOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <Box className={classes.dialog}>
          <Typography variant="h5" gutterBottom>{title}</Typography>
          <Grid container spacing={3}>
            {subFeatures?.map((feature, index) => (
              <Grid item xs={12} sm={6} key={index}>
                <Card className={classes.subFeatureCard}>
                  <Link to={feature.to} style={{ textDecoration: 'none', color: 'inherit' }}>
                    <CardContent>
                      <Box display="flex" alignItems="center">
                        <img className={classes.img} src={feature.imgUrl} alt={feature.title} />
                        <Box ml={3}>
                          <Typography variant="h6">{feature.title}</Typography>
                          <Typography variant="body2" color="textSecondary">
                            {feature.subTitle}
                          </Typography>
                        </Box>
                      </Box>
                    </CardContent>
                  </Link>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Box>
      </Dialog>
    </>
  );
}

FeatureBox.propTypes = {
  imgUrl: PropTypes.string,
  title: PropTypes.string,
  to: PropTypes.string,
  subTitle: PropTypes.string,
};

FeatureBox.defaultProps = {
  imgUrl: '',
  title: '',
  to: '',
  subTitle: '',
};

export default FeatureBox;
